def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda:f.read(1048576),b''):h.update(b)
    return h.hexdigest()

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    g=ap.add_mutually_exclusive_group(required=True);g.add_argument('--project-root',type=Path);g.add_argument('--checkpoint-root',type=Path)
    ap.add_argument('--output',type=Path,default=Path('EXP005_SELECTED_WEIGHTS_FOR_EXP012.zip'));args=ap.parse_args()
    root=args.checkpoint_root or args.project_root/'checkpoints/v2_exp005_command_tcn_tuned/confirm'
    indexed={f"{r['channel']}_seed{s}.pt":root/r['candidate']/f"{r['channel']}_seed{s}.pt" for r in ROSTER for s in [17,29,43]}
    missing=[str(p) for p in indexed.values() if not p.is_file()]
    if missing:raise SystemExit('No archive written. Missing selected checkpoints:\n'+'\n'.join(missing)+'\nUse --checkpoint-root pointing to the existing confirm directory. Do not retrain.')
    if args.output.exists():raise SystemExit('Output exists; preserve it or choose a new output filename.')
    args.output.parent.mkdir(exist_ok=True,parents=True);tmp=args.output.with_suffix('.zip.part')
    manifest={'purpose':'EXP012_SELECTED_EXP005_WEIGHTS','count':243,'files':{n:sha(p) for n,p in indexed.items()},
              'source_paths':{n:str(p) for n,p in indexed.items()},'operation':'byte-preserving transfer only; no model/data execution'}
    with zipfile.ZipFile(tmp,'w',zipfile.ZIP_DEFLATED,compresslevel=1) as z:
        for n,p in indexed.items():z.write(p,n)
        z.writestr('TRANSFER_MANIFEST.json',json.dumps(manifest,sort_keys=True,indent=2))
    os.replace(tmp,args.output);print('Wrote',args.output,'243 selected checkpoints; SHA256',sha(args.output))
if __name__=='__main__':main()
